    // 但宿主显式要求桌面模式（data-mobile-source=explicit）时兜底必须让位，否则侧栏被藏起来
    // 而布局仍按桌面预留宽度，只剩一条空槽。
    sidebarRoot: 'lt-md:hidden group-data-[mobile-source=explicit]/layout:block',
