      `absolute inset-y-0 z-[--vean-layout-sidebar-z-index] flex h-[--vean-layout-sidebar-height] w-[--vean-sidebar-width] transition-[width,opacity]-200 lt-md:hidden group-data-[mobile-source=explicit]/layout:flex`,
